import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Склад: остатки, приход, расход и инвентаризация"}>
      <p>{"Мы продаём товары для дома через маркетплейсы и свой сайт, у нас два склада в одном городе и пять кладовщиков. Остатки ведём в таблице, и она расходится с реальностью. Нужен складской учёт: справочник товаров (артикул, название, единица, категория, штрихкод), остатки по каждому складу и ячейке. Документы: приход от поставщика, расход под заказ, перемещение между складами, списание брака с причиной. Документ сначала черновик, остатки меняются только после проведения; провести расход больше остатка нельзя. Для каждого товара задаётся минимальный остаток — когда остаток ниже, закупщик получает уведомление на почту. Раз в квартал инвентаризация: кладовщик вносит фактическое количество по ячейкам, система показывает расхождения, а после утверждения руководителем создаёт корректировку. Кладовщик работает только со своим складом. Отчёты: оборот по товарам за период, товары без движения 90 дней, история движения конкретного товара. Сейчас поставки из Европы согласует клиент, его рабочий номер клиент."}</p>
      <ul>
        <li>{"Перемещение и списание"}</li>
        <li>{"Проведение документа"}</li>
        <li>{"Минимальный остаток и уведомление"}</li>
        <li>{"Ячейки хранения"}</li>
        <li>{"Расхождения при инвентаризации"}</li>
        <li>{"Товары без движения"}</li>
        <li>{"Отчёт по обороту"}</li>
      </ul>
      <p>{"Нельзя провести расход больше остатка"}</p>
      <p>{"Остатки меняются только после проведения"}</p>
      <p>{"Кладовщик видит только свой склад"}</p>
      <p>{"Корректировка после утверждения руководителем"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
